p=Path(__file__).parent
css='''@page{size:A4;margin:13mm}body{font-family:"Noto Sans CJK SC",sans-serif;color:#111;margin:0;font-size:15px;line-height:1.65}.page{break-after:page}.page:last-child{break-after:auto}h1{font-size:23px;text-align:center;margin:0 0 8px}h2{font-size:17px;margin:16px 0 9px}.meta{font-size:12px;margin-bottom:10px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:10px 25px}.calc{display:grid;grid-template-columns:repeat(4,1fr);gap:17px 8px;font-size:17px}.q{margin:12px 0}.space{height:45px}.smallspace{height:28px}.group{display:inline-block;border:1px solid #444;border-radius:12px;padding:6px 10px;margin:4px;font-size:18px}.line{border-bottom:1px solid #aaa;height:25px}.note{font-size:12px;color:#333}.key{font-size:14px}table{border-collapse:collapse;width:100%}td,th{border:1px solid #555;padding:6px;text-align:center}'''
calc=['4*3','5*6','6*6','2*5','18/3','24/6','20/4','30/5','3*5+4','6*4-5','12+3*6','30-4*5']; expected=[12,30,36,10,6,4,5,6,19,19,30,10];assert [eval(x) for x in calc]==expected
head='<!doctype html><meta charset="utf-8"><style>'+css+'</style>'
g=lambda n,k:''.join('<span class="group">'+'●'*k+'</span>' for _ in range(n))
s=head+'''<section class="page"><h1>二年级数学期中复习卷</h1><div class="meta">姓名：____________　日期：____________　用时：________<br>范围：第一至第三单元相关练习（1—6的乘除）｜满分100分｜建议35—40分钟<br>按顺序独立完成；需要时可画图或写中间过程。</div><h2>一、计算（每题2分，共24分）</h2><div class="calc">'''
for i,e in enumerate(calc,1):s+=f'<div>{i}. '+e.replace('*','×').replace('/','÷').replace('-','－').replace('+','＋')+'＝____</div>'
s+='''</div><h2>二、看图列式（共20分）</h2><div class="q">1. 一共有多少个圆点？写一道乘法算式。（4分）<br>'''+g(4,3)+'''<br>算式：________________________</div><div class="q">2. 18个圆点平均分在下面3个框里。每框几个？（4分）<br>'''+g(3,6)+'''<br>算式：________________________</div><div class="q">3. 18个圆点，每3个圈成一组。能圈几组？（4分）<br>'''+g(6,3)+'''<br>算式：________________________</div><div class="q">4. 写出一道乘加算式和一道乘减算式，求圆点总数。（各4分）<br>'''+g(3,5)+g(1,4)+'''<br>乘加：________________________<br>乘减：________________________</div><div class="note">第1页 / 共3页</div></section>'''
s+='''<section class="page"><h1>二年级数学期中复习卷</h1><h2>三、读懂除法（共20分）</h2><div class="q">1. 有12支铅笔，平均分给3个小朋友，每人分到几支？<br>先画图表示分法，再列式解答。（6分）<div class="space"></div>算式：________________________<br>答：____________________________________</div><div class="q">2. 有12支铅笔，每个小朋友分3支，可以分给几个小朋友？<br>先画图表示分法，再列式解答。（6分）<div class="space"></div>算式：________________________<br>答：____________________________________</div><div class="q">3. 上面两题都可以写成12÷3＝4。填一填。（每空2分，共8分）<br>第1题：3表示________________；4表示________________。<br>第2题：3表示________________；4表示________________。</div><h2>四、解决问题（本部分共36分）</h2><div class="q">1. 小林有两盒玻璃球，一盒5颗，另一盒3颗；小华有3盒玻璃球，每盒5颗。<br>（1）小林一共有多少颗？（3分）<div class="smallspace"></div>答：____________________________________<br>（2）小华一共有多少颗？（3分）<div class="smallspace"></div>答：____________________________________</div><div class="note">第2页 / 共3页</div></section>'''
s+='''<section class="page"><h1>二年级数学期中复习卷</h1><h2>四、解决问题（续）</h2><div class="q">2. 有24支毛笔，每个笔筒放6支，需要几个笔筒？（5分）<div class="smallspace"></div>答：____________________________________</div><div class="q">3. 有20个饺子，需要几个盘子？选择一个合适的条件，再列式解答。（5分）<br>① 每个盘子放4个饺子。　② 平均放在4个盘子里。<br>我选（　）。算式：________________________<br>答：____________________________________</div><table><tr><th>商品</th><th>沙包</th><th>水枪</th><th>魔方</th><th>纸风车</th></tr><tr><td>单价</td><td>3元/个</td><td>4元/把</td><td>6元/个</td><td>2元/个</td></tr></table><div class="q">4. 买1个魔方和3个纸风车，一共需要多少元？（5分）<div class="smallspace"></div>答：____________________________________</div><div class="q">5. 根据价格表，提出一个用<strong>除法</strong>解决的问题，并解答。（6分）<br>问题：________________________________________________<br>______________________________________________________<br>算式：________________　答：________________________</div><div class="q">6. 买10朵同样的纸花，下面哪种方案花钱更少？（9分）<br>方案A：每朵3元，买4朵送1朵。<br>方案B：每束5朵，每束14元。<br>方案A需要：________________________________________<br>方案B需要：________________________________________<br>答：________________________，少花________元。</div><div class="note">交卷前检查：有没有漏题？算式和答句是否写完整？答案表示什么，单位是否合适？<br>第3页 / 共3页</div></section>'''
p.joinpath('worksheet.html').write_text(s)
answers=[('一、计算（24分）','依次：12、30、36、10；6、4、5、6；19、19、30、10。每题2分。'),('二、看图列式（20分）','1. 3×4＝12（个），4×3也可。<br>2. 18÷3＝6（个）。<br>3. 18÷3＝6（组）。<br>4. 5×3＋4＝19（个）；5×4－1＝19（个）。乘法因数互换可接受。<br>每道算式4分：关系2分、计算1分、单位1分。'),('三、读懂除法（20分）','1. 画3组，每组4支；12÷3＝4（支），每人4支。<br>2. 每3支一组，画4组；12÷3＝4（个），可分给4个小朋友。<br>前两题各6分：图2分、算式及得数2分、单位和答句各1分。<br>3. 第一题：3个小朋友；每人4支。第二题：每人3支；4个小朋友。每空2分，等价表述可接受。'),('四、解决问题（36分）','1.（1）5＋3＝8（颗）；（2）5×3＝15（颗）。各3分：关系1、结果1、单位与答句1。<br>2. 24÷6＝4（个），需要4个笔筒。5分：关系2、结果1、单位1、答句1。<br>3. 选①；20÷4＝5（个），需要5个盘子。5分：选择1、关系1、结果1、单位1、答句1。<br>4. 6＋2×3＝12（元），需要12元。也可分两步列式。5分：关系2、结果1、单位1、答句1。<br>5. 开放题。例如：12元可以买几把水枪？12÷4＝3（把），可以买3把。6分：问题完整且用除法3分、列式计算2分、单位和答句1分。其他条件充分、符合价格表且能用1—6口诀求解的除法问题也可。<br>6. A：买8朵送2朵，得到10朵；3×4＋3×4＝24（元）。B：14＋14＝28（元）。A少花28－24＝4（元）。9分：A方案分组/赠送理解2分、计算1分；B方案理解2分、计算1分；比较选择1分、差额1分、单位与答句1分。<br>不要求使用三八口诀；学生若用3×8＝24同样接受，但教学可用两组买四送一解释。')]
k=head+'<section class="page key"><h1>期中复习卷 · 家长答案与评分</h1>'
for title,text in answers[:3]:k+='<h2>'+title+'</h2><div>'+text+'</div>'
k+='</section><section class="page key"><h1>答案与评分（续）</h1><h2>'+answers[3][0]+'</h2><div>'+answers[3][1]+'</div><h2>观察与复习建议</h2><p>总分100分，仅为本练习参考评分，不是学校评分标准。先独立完成，再讲解；提示后完成须单独注明。</p><p>重点比较三1、三2：两题算式一样，分组动作和结果含义不同。能算而不能解释时，不认定除法概念已稳。</p><p>单位漏写与写错分别记录；要求孩子解释答案表示什么。能解释但未写，偏向检查与表达；解释不清需再用实物分组。</p><p>四5必须提出除法问题。加法问题即使算对，也未满足任务要求。学生题面不提前给出例题。</p><p>本卷以老师通知及上传学校卷题型为依据，不宣称完整覆盖未核实教材所有知识点；不纳入100连续退位专项或7—9口诀。两种促销方案的高阶题放末尾，允许画图或分步。</p></section>'
p.joinpath('answer-key.html').write_text(k);p.joinpath('answer-key.md').write_text('\n\n'.join(t+'\n'+v.replace('<br>','\n') for t,v in answers))
p.joinpath('answer-manifest.json').write_text(json.dumps({'sections':answers,'source_mapping':{'一':'学校通知计算范围1—6乘除','二':'解决问题卷看图、乘加乘减','三':'家长反馈除法含义不清；分物与分组对照','四1':'玻璃球加法乘法对照','四2':'毛笔题单位','四3':'饺子选条件','四4':'玩具价格表','四5':'自编题未按运算要求','四6':'买四送一与整束价格比较'},'review':'答案与分值已核验；图形为实际分组圆点；PDF视觉预览待工具支持'},ensure_ascii=False,indent=2));p.joinpath('worksheet-spec.json').write_text(json.dumps({'title':'二年级期中复习卷','status':'已生成/待完成','scope':'老师通知1—6乘除；校卷题型','points':[24,20,20,36],'student_pages':3,'answer_pages':2},ensure_ascii=False,indent=2));assert sum([24,20,20,36])==100
